@startuml

class User {
  + id : int
  + name : string
  + address : string
  + birthday : date
}

abstract class Role {}
interface BusinessOwner extends Role {}
interface HungryCustomer extends Role {}
interface Entertainer extends Role {}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : string
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + id : int
  + orderDateAndTime : datetime
  + latestDeliveryTime : datetime
  + numberOfPeople : int
}

class EntertainmentOrder extends Order {
  + entertainmentType : string
  + duration : time
}

class EntertainerProfile {
  + stageName : string
  + bio : string
  + pricePer30Minutes : double
}

class Availability {
  + day : string
  + available : boolean
}

User "1" --|> BusinessOwner : is
User "1" --|> HungryCustomer : is
User "1" --|> Entertainer : is

BusinessOwner "1" *-- PizzaRestaurant : owns
PizzaRestaurant "*" -- "0..*" Pizza : offers
HungryCustomer "1" *-- Order : makes
Order "1" *-- Pizza : contains
Order "1" ..|> EntertainmentOrder : can be
Entertainer "1" -- "1..*" EntertainerProfile : has
Entertainer "*" -- Availability : worksOn

@enduml

